lib='''"""Reusable grid functions for ARC tasks."""
from collections import Counter

def nonzero_counts(grid):
    """Counter of the grid\'s nonzero cell colors."""
    return Counter(v for row in grid for v in row if v != 0)

def frame_color(grid):
    """The most common nonzero color of the grid."""
    return nonzero_counts(grid).most_common(1)[0][0]

def draw_color_lines(grid, colors=None):
    """Fill every background (0) cell lying strictly between two same-color cells
    of a given color, along their shared row or column; colors defaults to every
    nonzero color except the frame color and the most common of the rest."""
    cnt = nonzero_counts(grid)
    frame = cnt.most_common(1)[0][0]
    rest = Counter({c: n for c, n in cnt.items() if c != frame})
    if colors is None:
        maj = rest.most_common(1)[0][0] if rest else None
        colors = {c for c in rest if c != maj}
    out = [row[:] for row in grid]
    cells = {}
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v in colors:
                cells.setdefault(v, []).append((i, j))
    for c, ps in cells.items():
        for a in ps:
            for b in ps:
                if a >= b:
                    continue
                if a[0] == b[0]:
                    for j in range(a[1] + 1, b[1]):
                        if out[a[0]][j] == 0:
                            out[a[0]][j] = c
                if a[1] == b[1]:
                    for i in range(a[0] + 1, b[0]):
                        if out[i][a[1]] == 0:
                            out[i][a[1]] = c
    return out
